import type { Player } from './index';

export const squad: Player[] = [
  // Porteros
  { number: 1, name: 'Zion Suzuki', position: 'GK', age: 23, club: 'Parma', bio: { "es": "Suzuki, el primer portero japonés en establecerse como titular de la Serie A, es atlético, un tapón sólido y también tiene una gran distribución, capaz de llegar profundamente al campo contrario. Desde que llegó al Parma en 2024 procedente del Sint-Truiden belga, se ha dedicado a aprender italiano y ahora lo habla con fluidez. También habla abiertamente de sus ambiciones: “Quiero convertirme en uno de los mejores porteros del mundo y ganar la Liga de Campeones… Puede que suene poco realista, como algo sacado de un anime, pero nunca se sabe lo que puede pasar”. Su determinación y rápido desarrollo continúan alimentando grandes expectativas. Fuera de la cancha es un gran fanático del café: abrazó la cultura del espresso italiano, pero también compró un molinillo para moler sus propios granos en casa.", "en": "The first Japanese goalkeeper to establish himself as a Serie A regular, Suzuki is athletic, a solid shot-stopper, and has strong distribution, too – capable of reaching deep into the opposition half. Since joining Parma in 2024 from Belgium’s Sint-Truiden he has dedicated himself to learning Italian and now speaks it fluently. He also speaks openly about his ambitions: “I want to become one of the best keepers in the world and win the Champions League … That might sound unrealistic, like something out of an anime, but you never know what could happen.” His determination and rapid development continue to fuel high expectations. Off the pitch he is a big coffee fan: he has embraced Italy’s espresso culture, but also bought a grinder to grind his own beans at home." }, special: "No 1 goalkeeper" },
  { number: 12, name: 'Keisuke Osako', position: 'GK', age: 26, club: 'Sanfrecce Hiroshima', bio: { "es": "En su primera temporada profesional con Sanfrecce Hiroshima allá por 2018, Osako se dedicó a una incesante superación personal, añadiendo sesiones individuales adicionales después del entrenamiento matutino e incluso uniéndose a los entrenamientos del equipo juvenil por las tardes. Esa ética de trabajo lo ha llevado a un Mundial. Sólido portero, también es conocido por ser un brillante comunicador cuando dirige la defensa que tiene delante. Nombra a los ex internacionales japoneses Yoshikatsu Kawaguchi y Eiji Kawashima como sus modelos a seguir, pero dice que está más concentrado en serlo él mismo: \"Cuando la gente piensa en el guardián de Japón, quiero que piensen en Osako\".", "en": "In his first professional season with Sanfrecce Hiroshima back in 2018 Osako devoted himself to relentless self-improvement, adding extra individual sessions after morning training and even joining youth team training in the afternoons. That work ethic has taken him to a World Cup. A solid shot-stopper, he is also known for being a brilliant communicator when marshalling the defence in front of him. He names former Japan internationals Yoshikatsu Kawaguchi and Eiji Kawashima as his role models, but says he’s more focused on being one himself: “When people think of Japan’s guardian, I want them to think of Osako.”" } },
  { number: 23, name: 'Tomoki Hayakawa', position: 'GK', age: 27, club: 'Kashima Antlers', bio: { "es": "Un tardío que obtuvo su primera convocatoria a los 26 años. Hayakawa, conocido por sus rápidos reflejos y su aguda reacción a los segundos balones, jugó un papel clave para ayudar al Kashima Antlers a asegurar su primer título de liga en nueve años la temporada pasada. Hace un par de años comenzó a trabajar con un entrenador personal para reevaluar la mecánica de su cuerpo y su rango de movimiento, y ha seguido elevando sus niveles de rendimiento. Estuvo en el banco en el amistoso internacional del pasado octubre contra Brasil, pero no estará satisfecho hasta que obtenga el estatus de primera opción, y sabe que tendrá que demostrar su capacidad al más alto nivel para lograrlo. \"A menos que pueda detener a alguien como Mbappé uno a uno, no puedo realmente competir por un puesto titular\".", "en": "A late bloomer who earned his first call-up at 26. Hayakawa, known for quick reflexes and being sharp reacting to second balls, played a key role in helping Kashima Antlers secure their first league title in nine years last season. A couple of years ago he began working with a personal trainer to reassess his body mechanics and range of motion, and has continued to elevate his performance levels. He made the bench in last October’s international friendly against Brazil, but won’t be satisfied until he earns first-choice status – and knows he will have to prove his ability at the top level to do so. “Unless I can stop someone like Mbappé one-on-one, I can’t truly compete for a starting spot.”" } },
  // Defensores
  { number: 2, name: 'Yukinari Sugawara', position: 'DF', age: 25, club: 'Southampton', bio: { "es": "La gran baza de Sugawara es su explosividad corriendo por el flanco derecho, lo que lo convierte en una verdadera amenaza de ataque. Pero también es sólido atrás, capaz de cambiar de marcha para ofrecer una defensa agresiva uno contra uno. A los 18 años, cuando se mudó al AZ Alkmaar en los Países Bajos, se acercó al chef personal de su compañero de equipo internacional Yuto Nagatomo para aprender sobre dieta y nutrición desde cero. \"Sentí una enorme brecha entre la comida holandesa y la japonesa\", dijo, \"y tuve la sensación de que podría lastimarme si no lo abordaba\". Vivir con una familia anfitriona significaba que tenía acceso limitado a la cocina, pero lo aprovechó al máximo. De allí se mudó a Inglaterra con el Southampton en 2024 y se unió al Werder Bremen en calidad de préstamo la temporada pasada.", "en": "Sugawara’s big asset is his explosive running down the right flank, making him a real attacking threat. But he is solid at the back, too, able to switch gears to deliver aggressive one-on-one defending. At 18, when he moved to AZ Alkmaar in the Netherlands, he reached out to international teammate Yuto Nagatomo’s personal chef to learn about diet and nutrition from scratch. “I just felt a huge gap between Dutch and Japanese food,” he said, “and I had a sense that I might get injured if I didn’t address it.” Living with a host family meant he had limited access to the kitchen, but he made the most of it. He moved from there to England with Southampton in 2024, and joined Werder Bremen on loan last season." } },
  { number: 3, name: 'Shogo Taniguchi', position: 'DF', age: 34, club: 'Sint-Truiden', bio: { "es": "Un defensor versátil capaz de jugar en cualquier lugar de la línea defensiva, la inteligencia futbolística y la distribución de Taniguchi lo distinguen. Le da especial importancia a su campo de visión, siendo consciente de todo lo que le rodea, en parte porque su vista se deterioró durante sus años de estudiante. Desde entonces ha sido meticuloso en la preparación de lentes de contacto y en el cuidado adecuado de sus ojos. Su entrenador de secundaria lo describió una vez como alguien que “demuestra dedicación y liderazgo para el equipo incluso fuera de la cancha... no hay una sola persona que hablaría mal de Shogo”. Su carácter y liderazgo han sido ampliamente respetados durante mucho tiempo. Juega al fútbol de su club en Bélgica desde 2024 y, en la selección nacional, sigue demostrando su fiabilidad como líder defensivo.", "en": "A versatile defender capable of playing anywhere across the back line, Taniguchi’s football intelligence and distribution set him apart. He places particular importance on his field of vision, being aware of everything around him, partly because his eyesight deteriorated during his student years. Since then he has been meticulous about preparing contact lenses and taking proper care of his eyes. His high school coach once described him as someone who “demonstrates dedication and leadership for the team even off the pitch … there isn’t a single person who would speak ill of Shogo.” His character and leadership have long been widely respected. He has played his club football in Belgium since 2024 and, in the national team, continues to show his reliability as a defensive leader." } },
  { number: 4, name: 'Ko Itakura', position: 'DF', age: 29, club: 'Ajax', bio: { "es": "Después de pasar tres temporadas en el Borussia Mönchengladbach, Itakura se unió al gigante holandés Ajax el año pasado, convirtiéndose en el primer jugador japonés en la historia del club. Un defensor sólido y experimentado que estuvo en los libros del Manchester City de 2019 a 2022 sin abrirse paso, sobresale en la defensa uno a uno, pero también aporta verdadera versatilidad. Jugó como mediocampista defensivo durante sus años en la academia, por lo que tiene la compostura y la técnica para reaccionar bajo presión y contribuir a la preparación desde atrás. También es conocido por su personalidad alegre y abierta. Su madre cree que su notable capacidad para adaptarse rápidamente y encajar puede deberse a su primera infancia, cuando pasó los primeros seis años y medio de su vida viviendo en viviendas de la empresa compartidas por unas 60 familias.", "en": "After spending three seasons at Borussia Mönchengladbach, Itakura joined Dutch giants Ajax last year, becoming the first Japanese player in the club’s history. A solid, experienced defender who was on Manchester City’s books from 2019 to 2022 without breaking through, he excels in one-on-one defending, but also brings real versatility. He played as a defensive midfielder during his academy years, so has the composure and technique to turn under pressure and contribute to the build-up from the back. He is also known for his cheerful and open personality. His mother believes his remarkable ability to adapt quickly and fit in may stem from his early childhood when he spent the first six-and-a-half years of his life living in company housing shared by around 60 families." }, special: "Cheerful personality" },
  { number: 5, name: 'Yuto Nagatomo', position: 'DF', age: 39, club: 'FC Tokyo', bio: { "es": "Como miembro de mayor edad del equipo, Nagatomo aporta un liderazgo apasionado respaldado por una carrera larga y distinguida. Sus repetidos gritos de “¡Bravo!” en las entrevistas posteriores a los partidos tras las victorias de Japón sobre Alemania y España en el Mundial de Qatar se han convertido desde entonces en su marca registrada. Cumplirá 40 años este septiembre y solo es superado por Yasuhito Endo en el ranking de jugadores con más partidos internacionales de Japón, y no muestra signos de desaceleración. “Mis células están explotando”, bromea. \"En todo caso, deberías preocuparte de que mejore\". Con un ritmo de trabajo incesante, una condición física excepcional y una actitud intransigente, continúa marcando el estándar para los jugadores más jóvenes y aporta una amplia experiencia en el fútbol de clubes europeos, ya que jugó para el Inter de Milán, el Galatasaray y el Marsella antes de fichar por el FC Tokio en 2021. Con una quinta aparición en la Copa del Mundo a punto de llegar, su pasión y obsesión por actuar en el escenario más grande siguen ardiendo con más fuerza que nunca.", "en": "As the oldest member of the squad, Nagatomo brings famously passionate leadership backed by a long and distinguished career. His repeated cries of “Bravo!” in post-match interviews after Japan’s victories over Germany and Spain at the Qatar World Cup have since become his trademark. Turning 40 this September, and second only to Yasuhito Endo in Japan’s most-capped rankings, he shows no signs of slowing down. “My cells are exploding,” he jokes. “If anything, you should be worried about me improving.” With relentless work rate, exceptional physical conditioning and an uncompromising attitude, he continues to set the standard for younger players, and brings broad European club football experience, having played for Inter Milan, Galatasaray and Marseille before signing for FC Tokyo in 2021. With a fifth World Cup appearance coming up, his passion and obsession with performing on the biggest stage continue to burn as fiercely as ever." }, special: "Golden oldie" },
  { number: 16, name: 'Tsuyoshi Watanabe', position: 'DF', age: 29, club: 'Feyenoord', bio: { "es": "Después de pasar del FC Tokyo al Gent en 2021, se convirtió en uno de los jugadores más destacados del equipo belga, ganando el premio al Jugador del Año del club en la temporada 2024-25. Construido sobre una base física poderosa, rara vez muestra debilidad en los duelos. También es dominante en el juego aéreo, utiliza su anticipación para ganar cabezazos en los puntos altos y representa una amenaza en situaciones de balón parado con su capacidad goleadora. Tras elevar su perfil en la liga belga, consiguió el fichaje por el Feyenoord holandés el año pasado. \"No quiero dejar la defensa en manos de otros, quiero organizar y liderar la línea de fondo yo mismo\", dice. \"No siento presión en este momento; estoy emocionado de ver hasta dónde puedo llegar\".", "en": "After moving from FC Tokyo to Gent in 2021 he developed into one of the Belgian team’s standout players, earning the club’s Player of the Year award in the 2024-25 season. Built on a powerful physical foundation, he rarely shows any weakness in duels. He is also dominant in the air, using his anticipation to win headers at a high point, and poses a threat in set-piece situations with his goalscoring ability. Having raised his profile in the Belgian league he secured a move to Dutch giants Feyenoord last year. “I don’t want to leave defending to others, I want to organise and lead the back line myself,” he says. “I don’t feel pressure right now; I’m excited to see how far I can go.”" } },
  { number: 20, name: 'Ayumu Seko', position: 'DF', age: 25, club: 'Le Havre', bio: { "es": "Un defensor que sobresale en leer el juego y superar a sus oponentes mediante inteligencia y anticipación. También es eficaz en la posesión, con pases precisos para construir desde atrás. Se unió a la Ligue 1 Le Havre procedente del Grasshopper Zurich el año pasado, convirtiéndose en el primer jugador japonés del club. Cuando era niño se inspiró en el popular manga japonés Detective Conan. \"Cuando Conan aprieta el botón de su cinturón, sale una pelota. Siempre soñé con patearla como él\", recuerda. También es versátil como el detective Conan. \"Soy el único que puede jugar en todas las posiciones con una defensa de tres\", dice. Su capacidad para desempeñarse a un alto nivel independientemente de la posición lo convierte en un activo invaluable este verano.", "en": "A defender who excels in reading the game and outmaneuvering opponents through intelligence and anticipation. He is also effective in possession, with precise passing to build from the back. He joined Ligue 1 Le Havre on a free from Grasshopper Zurich last year, becoming the club’s first ever Japanese player. As a child he was inspired by the popular Japanese manga Detective Conan. “When Conan presses the button on his belt, a ball comes out. I always dreamed of kicking it like him,” he recalls. He is versatile like Detective Conan, too. “I’m the only one who can play all positions in a back three,” he says. His ability to perform at a high level regardless of position makes him an invaluable asset this summer." } },
  { number: 21, name: 'Hiroki Ito', position: 'DF', age: 26, club: 'Bayern Munich', bio: { "es": "Después de pasar del Júbilo Iwata en J2 a Stuttgart en 2021, Ito rápidamente se estableció como un verdadero talento en el fútbol europeo. Reconocido por su excepcional precisión con la zurda y su distribución de largo alcance, combina la fuerza física en los duelos con una mentalidad agresiva, mientras que su posicionamiento inteligente y su cobertura niegan tiempo y espacio a sus oponentes. Hizo una gran transferencia al Bayern de Múnich en 2024 y, a pesar de sufrir tres lesiones graves poco después de unirse, se recuperó con fuerza para convertirse en una gran presencia en su línea de fondo. Se siente como en casa en Alemania y el año pasado le dijo al sitio web del Bayern que hay \"sushi realmente bueno en Munich\". Y añadió: \"Soy una persona japonesa típica. La cortesía es muy importante para mí. Las mentalidades alemana y japonesa son similares, con limpieza, cortesía y puntualidad. Pero no soy tímido. Siempre lucho durante 90 minutos en el campo\".", "en": "After moving from Júbilo Iwata in J2 to Stuttgart in 2021 Ito quickly established himself as a real talent in European football. Renowned for his exceptional left-footed precision and his long-range distribution, he combines physical strength in duels with an aggressive mindset, while his intelligent positioning and covering deny opponents time and space. He made a big-money move to Bayern Munich in 2024 and, despite suffering three serious injuries soon after joining, he made a strong recovery to become a big presence in their back line. He feels at home in Germany, telling Bayern’s website last year there’s “really good sushi in Munich”. He added: “I’m a typical Japanese person. Politeness is very important to me. The German and Japanese mentalities are similar, with cleanliness, politeness and punctuality. But I’m not shy. I always fight for 90 minutes on the pitch.”" }, special: "Defensive rock" },
  { number: 22, name: 'Takehiro Tomiyasu', position: 'DF', age: 28, club: 'Ajax', bio: { "es": "Pocos jugadores inspiran tanta confianza a través de su coherencia e integridad como Takehiro Tomiyasu. Su carácter se ha mantenido sin cambios desde la infancia. Durante sus años de escuela secundaria, llegaba a las sesiones de fútbol antes que los demás para preparar las cosas y se quedaba atrás para limpiar. “Si llego temprano y preparo todo, los entrenamientos pueden empezar de inmediato”, afirmó. Dominante en el juego aéreo, fuerte físicamente en los duelos y dotado de una agilidad impresionante, posee todos los atributos necesarios de un defensor de primer nivel. Si bien puede hacer un trabajo en cualquier flanco como lateral, es en la defensa central donde destacan su compostura y estabilidad. Se mudó al Arsenal en 2021 procedente de Bolonia por £ 17 millones, pero su estancia en Londres se vio obstaculizada por lesiones y finalmente terminó con una grave lesión en la rodilla que requirió cirugía. Dejó el club el verano pasado, pero el Ajax lo contrató con un contrato a corto plazo en diciembre. Si puede demostrar que se ha recuperado por completo de su forma física para el partido, debería ser un jugador clave este verano.", "en": "Few players inspire as much trust through their consistency and integrity as Takehiro Tomiyasu. His character has remained unchanged since childhood. During his middle school years he would arrive for football sessions before everyone else to set up, and stay behind to clean up. “If I arrive early and prepare everything, training can start right away,” he said. Dominant in the air, physically strong in duels, and equipped with impressive agility, he possesses all the attributes required of a top-level defender. While he can do a job on either flank as a full-back, it’s at centre-back where his composure and stability stand out. He moved to Arsenal in 2021 from Bologna for £17m but his time in London was hampered by injuries, and was ultimately ended by a serious knee injury which required surgery. He left the club last summer, but was picked up by Ajax on a short-term deal in December. If he can prove he has fully recovered match fitness, he should be a key player this summer." } },
  { number: 25, name: 'Junnosuke Suzuki', position: 'DF', age: 22, club: 'FC Copenhagen', bio: { "es": "En su tercera temporada profesional, Suzuki pasó de mediocampista defensivo a central, y la decisión dio sus frutos. El año pasado pasó del Shonan Bellmare del J1 al FC Copenhague y se ha ganado muchos elogios en Dinamarca por sus pases precisos con ambos pies y su capacidad para leer el juego. Pronto siguió una primera convocatoria y, en el amistoso internacional contra Brasil del pasado mes de octubre, jugó el partido completo, luciendo fuerte y seguro contra algunos de los mejores atacantes del mundo. Su experiencia como centrocampista le aporta un amplio campo de visión y compostura con el balón. Un ex entrenador de la escuela secundaria lo describe como alguien que “nunca se deja influenciar por sus emociones” y “siempre escucha con atención, incluso cuando la retroalimentación no está dirigida a él”.", "en": "In his third professional season Suzuki transitioned from a defensive midfielder to a centre-back, and the decision paid off. Last year he made the move from J1 side Shonan Bellmare to FC Copenhagen, and has earned plenty of praise in Denmark for his precise passing with both feet and his ability to read the game. A first call-up soon followed and, in the international friendly against Brazil last October, he played the full match, looking strong and assured against some of the world’s top attackers. His experience as a midfielder gives him a wide field of vision and composure on the ball. A former high school coach describes him as someone who is “never influenced by his emotions” and “always listens carefully, even when the feedback isn’t directed at him”." }, special: "Former midfielder" },
  // Volantes
  { number: 6, name: 'Wataru Endo', position: 'MF', age: 32, club: 'Liverpool', captain: true, bio: { "es": "Apodado \"El Rey del Duelo\" en Japón, Endo se destaca en la lectura del juego, usando su poderoso equilibrio en la parte superior del cuerpo para derribar a los oponentes. ¿Cuál es su secreto? \"En parte es cuestión de tiempo\", dijo a The Times. \"Una entrada no es simplemente golpear a tu oponente, tienes que estar en la posición correcta y tal vez ser inteligente y adivinar lo que está pensando un oponente, o la jugada que quiere hacer. Creo que los japoneses son inteligentes, así que puedes aprovechar el beneficio de eso para ganar un duelo. Esa es mi opinión de todos modos, y funciona para mí\". En febrero sufrió lo que parecía una lesión que pondría fin a su temporada en el partido del Liverpool contra el Sunderland; ha sido una batalla ansiosa para recuperar su forma física para este verano. Habló de la emoción del momento en ese momento y dijo: \"El médico me preguntó si podía levantarme y salir de la cancha, pero dije que no y estaba llorando un poco... No lloraba porque fuera doloroso, era porque nuestros fans estaban cantando mi canción y eso significa mucho para mí\". Fuera del campo, tiene muchos seguidores en línea en Japón por sus videoblogs y artículos sobre fútbol, ​​la vida y la crianza de los hijos, y ha escrito un libro de autoayuda llamado \"Duelo\", subtitulado \"30 formas de pensar que no necesitan respuestas correctas\".", "en": "Nicknamed “The Duel King” in Japan, Endo excels at reading the game, using his powerful upper-body balance to shut down opponents. What’s his secret? “Some of it is timing,” he told The Times. “A tackle is not just hitting against your opponent, you have to be in the right position and maybe be clever and guess what an opponent is thinking, or the play they want to make. Japanese, I think, are clever, so you can use the benefit of that to win a duel. That’s my opinion anyway, and it works for me.” In February he sustained what looked like a season-ending injury in Liverpool’s game against Sunderland – it has been an anxious battle to regain fitness for this summer. He spoke of the emotion of the moment at the time, saying: “The doctor asked me if I could stand up and walk off the pitch but I said no and I was crying a little bit … I was not crying because it was painful, it was because our fans were singing my song and that means a lot to me.” Off the pitch he has a big online following in Japan for his video blogs and articles about football, life and parenting, and has written a self-help book called “Duel”, subtitled “30 ways of thinking that don't need correct answers”." }, special: "‘The duel king’" },
  { number: 7, name: 'Ao Tanaka', position: 'MF', age: 27, club: 'Leeds', bio: { "es": "Desarrollado en la academia Kawasaki Frontale, la calidad técnica de Tanaka es clara, pero es su capacidad para cubrir áreas amplias en ambos extremos del campo y anticipar cambios en el juego lo que le da la ventaja. Capta el peligro desde el principio y también tiene un gran ojo para el gol, marcando en la victoria de Japón sobre España en la Copa Mundial de Qatar. Se le conoce como un ávido lector, organizando sus notas de lectura en torno a tres ejes: conocimiento, información y acción. Se trata de estructura y eficiencia. Su nombre significa \"azul\"; sus padres tenían un nombre diferente en mente, pero el cielo era tan azul el día que nació que eligieron ese. Una historia de su época de escuela primaria resume su empuje y determinación: durante su primera prueba para el equipo de la escuela, al principio jugaba alegremente, pero a mitad de camino la maestra lo vio llorando en un rincón del patio de la escuela. Cuando el profesor le preguntó qué pasaba, respondió: \"Estoy aburrido de esta práctica. Quiero practicar más\".", "en": "Developed in the Kawasaki Frontale academy, Tanaka’s technical quality is clear, but it’s his ability to cover wide areas at both ends of the pitch and anticipate shifts in play that gives him the edge. He reads danger early, and has a strong eye for goal, too, scoring in Japan’s win over Spain at the Qatar World Cup. He is known as an avid reader, organising his reading notes around three axes: knowledge, information and action. He’s all about structure and efficiency. His first name means “blue” – his parents had a different name in mind, but the sky was so blue on the day he was born, they chose that instead. One story from his elementary school days sums up his drive and determination: during his first trial for the school team he was playing happily at first, but halfway through the teacher spotted him crying in the corner of the schoolyard. When the teacher asked him what was wrong, he replied: “I'm bored with this practice. I want to practice harder.\"" }, special: "Keen reader" },
  { number: 15, name: 'Daichi Kamada', position: 'MF', age: 30, club: 'Crystal Palace', bio: { "es": "Un jugador con un elevado coeficiente intelectual futbolístico, definido por un ritmo de trabajo incansable y una aguda lectura del juego. Desde que se mudó a Inglaterra con el Palace procedente de la Lazio en 2024, Kamada ha vuelto a demostrar su flexibilidad táctica, capaz de actuar tanto como centrocampista ofensivo como en un papel más profundo. Su atención siempre ha estado en su ética de trabajo, incluso en los períodos de pretemporada, que una vez llamó “más una dificultad que un entrenamiento, y nadie entrena tanto como yo”. Aporta una gran experiencia a la selección nacional, habiendo jugado en las principales divisiones de Japón, Alemania, Italia, Bélgica e Inglaterra, y ayudó a Palace a ganar la Copa FA en su primera temporada. Publicó su biografía oficial en 2023, titulada: “Creencia inquebrantable: 12 personas dan testimonio de la historia de crecimiento del jugador de la selección nacional de fútbol de Japón, Daichi Kamada”.", "en": "A player with a high football IQ, defined by a tireless work rate and sharp reading of the game. Since moving to England with Palace from Lazio in 2024 Kamada has again proven his tactical flexibility, capable of operating both as an attacking midfielder and in a deeper role. His focus has always been on his work ethic, including in the pre-season periods, which he once called “more like hardship than training, and no one trains as much as I do”. He brings a wealth of experience to the national side, having played in the top divisions in Japan, Germany, Italy, Belgium and England, and he helped Palace win the FA Cup in his first season. He released his official biography in 2023, called: “Unwavering Belief: 12 People Testify to the Growth Story of Japan National Football Team Player Daichi Kamada.”" } },
  { number: 17, name: 'Yuito Suzuki', position: 'MF', age: 24, club: 'Freiburg', bio: { "es": "Un atacante versátil al que le gusta deslizarse más allá de los oponentes con hábiles fintas y un control suave. Capaz de jugar en la banda, en el centro o como delantero de sombra, Suzuki crea oportunidades y también las remata. En el centro de su juego se encuentra una clara filosofía personal basada en la fuerza de carácter. \"Es importante crecer como persona\", afirma. Cuando se mudó a Brøndby en Dinamarca, decidió no revelar a todos los que conocía que era futbolista, y quería ser juzgado como una persona \"normal\". \"Era tímido en Japón\", le dijo a GQ, \"pero después de ir a Dinamarca comencé a entablar conversaciones de manera proactiva. Me hice amigo del personal del café y de la gente que me presentaron. Quería ser simplemente un amigo normal, así que hay algunos a quienes no les conté que era un jugador\". Fichó por el Friburgo el año pasado por una tarifa de hasta 8 millones de libras esterlinas, lo que la convierte en la venta más lucrativa de Brøndby. El director deportivo del Friburgo, Jochen Saier, dijo que habían estado detrás de Suzuki durante \"mucho tiempo... puede marcar goles y ayudar a sus compañeros de equipo. Su ritmo, flexibilidad y técnica mejorarán nuestro juego de ataque en general\".", "en": "A versatile attacker who likes to glide past opponents with deft feints and smooth control. Capable of playing on the wing, in the middle or as a shadow striker, Suzuki creates chances and finishes them too. At the core of his game lies a clear personal philosophy based around strength of character. “It’s important to grow as a person,” he says. When he moved to Brøndby in Denmark he chose not to reveal to everyone he met that he was a footballer, wanting to be judged as a “normal” person instead. \"I was shy in Japan,” he told GQ, “but after going to Denmark I started to proactively strike up conversations. I became friends with café staff and people I was introduced to. I wanted to be just a normal friend, so there are some I didn't tell that I was a player.\" He signed for Freiburg last year for a reported fee of up to £8m, making him Brøndby’s most lucrative sale. Freiburg's chief sporting officer, Jochen Saier, said they had been after Suzuki for “a really long time … he can both score goals and set up his teammates. His pace, flexibility and technique will improve our overall attacking play.”" } },
  { number: 24, name: 'Kaishu Sano', position: 'MF', age: 25, club: 'Mainz', bio: { "es": "Siguiendo el consejo de su padre, un ex esquiador, Sano pasó gran parte de su infancia usando las tradicionales sandalias geta de madera. “Definitivamente me ayudó a desarrollar mi equilibrio”, dijo, y todavía se nota ahora, con una fuerza y ​​un movimiento sobresalientes en el core. Siempre es difícil quitarle el balón y combina la estabilidad en la posesión con la fuerza para recuperarla. Su hermano menor, Kodai, juega en el NEC Nijmegen de la liga holandesa y durante la clasificación final asiática ambos hermanos fueron convocados juntos para la selección nacional. En 2025, Japón lo volvió a llamar porque había quedado fuera del equipo desde su arresto el verano anterior bajo sospecha de agresión sexual. La investigación fue cerrada por un fiscal sin cargos. El entrenador de Japón, Hajime Moriyasu, dijo que Sano le había dado la impresión de que había \"reflexionado profundamente\" sobre el episodio, diciendo: \"¿Alguien que era parte de la familia del equipo debería ser expulsado de la sociedad y del fútbol por cometer un error?\". Sano emitió un comunicado diciendo: \"Lamento mucho haber causado problemas a tanta gente con mis acciones\".", "en": "Following the advice of his father, a former skier, Sano spent much of his childhood wearing traditional wooden geta sandals. “It definitely helped me develop my balance,” he said, and it still shows now, with outstanding core strength and movement. He’s always difficult to knock off the ball, combining stability in possession with the strength to win it back. His younger brother, Kodai, plays for NEC Nijmegen in the Dutch league, and during the Asian final qualifiers, both brothers were called up to the national team together. In 2025 he was recalled by Japan having been left out of the squad since his arrest the previous summer on suspicion of sexual assault. The investigation was closed by a public prosecutor without charges. Japan’s manager, Hajime Moriyasu, said Sano had given him the impression that he had \"reflected deeply\" on the episode, saying: “Should someone who was part of the family of the team be cast out of society and out of football for making a mistake?\" Sano issued a statement saying: “I am truly sorry for causing trouble to so many people with my actions.”" } },
  // Delanteros
  { number: 8, name: 'Takefusa Kubo', position: 'FW', age: 25, club: 'Real Sociedad', bio: { "es": "Un enorme talento, a menudo apodado “el Messi japonés”. Kubo fue un talento descubierto por el Barcelona a los ocho años y se unió a su academia de La Masia a los 10. En 2023 reveló lo dura que había sido la experiencia, diciendo: “Había muchos niños con personalidades fuertes en la escuela y en los dormitorios, así que traté de no perderme entre la multitud, o mejor dicho, pensé que si me menospreciaban aunque fuera un poco, sería el final, así que aunque era pequeño hice lo mejor que pude para no perder, pero aun así me golpearon. por niños más grandes. Realmente no puedo decir mucho, pero era un ambiente realmente difícil”. De todos modos, su progreso allí se detuvo cuando se descubrió que el club había violado la política de transferencias internacionales de la FIFA para menores de 18 años. En cambio, se desarrolló en el FC Tokyo antes de regresar a España con el Real Madrid en 2019. Su capacidad para atraer a los defensores con regates precisos y explosivos lo convierte en una gran amenaza, y es igualmente potente como creador de juego, entregando pases finales decisivos. También tiene mucha confianza en sí mismo y recientemente afirmó: \"No sólo soy bueno con el balón en los pies, creo que soy bueno en el fútbol en general\". Este verano es una oportunidad para mostrar su talento en un escenario global, con clubes de Inglaterra siguiendo su progreso.", "en": "A huge talent, often dubbed “the Japanese Messi”. Kubo was talent spotted by Barcelona at the age of eight, and joined their La Masia academy at 10. In 2023 he revealed how hard the experience had been, saying: “There were a lot of kids with strong personalities at school and in the dorms, so I tried not to get lost in the crowd, or rather, I thought that if I was looked down upon even a little, it would be the end, so even though I was small I tried my best not to lose, but I still got punched by bigger kids. I can't really say much, but it was a really tough environment.” His progress there was halted, anyway, when the club was found to have violated Fifa international transfer policy for Under-18s. Instead he developed at FC Tokyo before returning to Spain with Real Madrid in 2019. His ability to draw in defenders with sharp, explosive dribbling makes him a huge threat, and he is equally potent as a playmaker, delivering decisive final passes. He has plenty of self-confidence too, saying recently: “I’m not just good with the ball at my feet – I think I’m good at football as a whole.” This summer is a chance to showcase his talents on a global stage, with clubs in England tracking his progress." }, special: "‘The Japanese Messi’" },
  { number: 9, name: 'Keisuke Goto', position: 'FW', age: 21, club: 'Sint-Truidense', bio: { "es": "Cuando era niño, Goto probó suerte en una amplia gama de deportes, desde voleibol y atletismo hasta natación y tenis, antes de decidirse por el fútbol. Un imponente delantero de 1,91 m, se mudó a Europa en 2024 con Anderlecht, inicialmente en su equipo de reserva RSCA Futures, e hizo su debut absoluto con ellos el año pasado antes de unirse al Sint-Truiden en calidad de préstamo para continuar su desarrollo. Muchos grandes clubes de Inglaterra y Alemania lo han estado siguiendo, pero le da vergüenza que los medios belgas lo llamen “el Erling Haaland japonés”, y le dijo al Times en marzo: “¡No, no, no!”. Pero admitió que intenta seguir el modelo de Harry Kane debido al \"movimiento sin balón\" del delantero inglés, sabiendo cómo profundizar, crear y disparar desde fuera del área.", "en": "As a child Goto tried his hand at a wide range of sports from volleyball and track and field to swimming and tennis, before settling on football. A towering striker at 1.91m, he made the move to Europe in 2024 with Anderlecht, initially in their reserve side RSCA Futures, and made his senior debut for them last year before joining Sint-Truiden on loan to continue his development. Plenty of big clubs in England and Germany have been tracking him, but he is shy about being called “the Japanese Erling Haaland” by Belgian media, telling The Times in March: “No, no, no!” But he did admit he tries to model himself on Harry Kane because of the England striker’s “movement off the ball, knowing how to drop deep, to create and shoot from outside the box”." } },
  { number: 10, name: 'Ritsu Doan', position: 'FW', age: 27, club: 'Eintracht Frankfurt', bio: { "es": "En el Mundial de Qatar, Doan anotó contra Alemania y España, afianzando su pretensión de ser la principal amenaza ofensiva de Japón. Cortando desde la derecha a gran velocidad, representa una amenaza constante con su potente disparo con la zurda. A pesar de medir sólo 1,73 m, también es fuerte físicamente. Su capacidad para rendir en el escenario más grande significa que a menudo se le ha comparado con la ex estrella japonesa Keisuke Honda, no sólo por su estilo sino también por su fuerte sentido de confianza en sí mismo. Dijo en febrero: \"Tengo la sensación de que la gente depende de mí... Quiero ser el tipo de jugador que haga de su equipo un equipo ganador. Creo que necesitamos el tipo de jugadores con los que el entrenador y el equipo puedan sentir: 'Sé que puedo contar con Ritsu cuando esté cerca', o 'Ritsu puede ayudarnos a calmarnos incluso cuando las cosas se ponen difíciles', o 'si él se mantiene fuerte, nosotros también nos mantendremos sólidos', ese tipo de cosas. Los mejores equipos siempre tienen jugadores así\". Ha jugado al fútbol de su club en Alemania desde 2020, inicialmente cedido en el Arminia Bielefeld procedente del PSV, luego con el Friburgo y, desde el año pasado, con el Eintracht Frankfurt tras una transferencia de £ 18 millones.", "en": "At the Qatar World Cup Doan scored against both Germany and Spain, staking his claim to be Japan’s leading attacking threat. Cutting in from the right at speed he poses a constant threat with his powerful left-footed shot. Despite being just 1.73m he is physically strong, too. His ability to deliver on the biggest stage means he has often been compared to former Japan star Keisuke Honda, not only for his style but also for his strong sense of self-belief. He said in February: “I do have the sense that people are depending on me … I want to be the kind of player who makes his team a winning team. I think we need the kind of players where the coach and the team can feel like ‘I know that I can count on Ritsu when he’s around’, or ‘Ritsu can help us settle down even when things get tricky’, or ‘if he’s standing strong, we stay solid as well’, that sort of thing. The best teams always have players like that.” He has played his club football in Germany since 2020, initially on loan at Arminia Bielefeld from PSV, then with Freiburg and, since last year, with Eintracht Frankfurt following an £18m move." }, special: "Big-game player" },
  { number: 11, name: 'Daizen Maeda', position: 'FW', age: 28, club: 'Celtic', bio: { "es": "Un atacante versátil y físico, los grandes puntos fuertes de Maeda residen en su presión implacable y sus carreras explosivas: está entre los jugadores más rápidos de la selección nacional. Su habilidad para reprimir a sus oponentes con movimientos sutiles y silenciosos le valió el apodo de \"Prius\" en la escuela secundaria. Sin embargo, su estancia allí no siempre fue tranquila: en su primer año estuvo involucrado en un incidente disciplinario que lo llevó a un largo período sin jugar al fútbol en la escuela; respondió comprometiéndose a entrenar más y jugar para un equipo amateur local, mientras también forjaba su carácter trabajando a tiempo parcial en una panadería por las mañanas antes de que comenzaran las clases. Continuó construyendo una carrera exitosa y ha sido un gran jugador en el Celtic desde que se mudó a Escocia en 2021, ganándose su propio cántico, con fanáticos cantando su nombre al son del clásico “Tequila” de The Champs. Maeda les ha agradecido online por “su maravillosa canción”.", "en": "A versatile, physical attacker, Maeda’s big strengths lie in his relentless pressing and explosive sprinting: he’s among the fastest players in the national team. His knack for closing down opponents with subtle, quiet movement earned him the nickname “Prius” in high school. His time there wasn’t always smooth, though: in his first year he was involved in a disciplinary incident that led to a lengthy spell of no school football; he responded by committing himself to extra training and playing for a local amateur side, while also building character by working part-time at a bakery in the mornings before school started. He went on to build a successful career, and has been a big player at Celtic since moving to Scotland in 2021, earning his own chant, with fans singing his name to the tune of The Champs’ classic “Tequila”. Maeda has thanked them online for “their wonderful song”." } },
  { number: 13, name: 'Keito Nakamura', position: 'FW', age: 25, club: 'Stade de Reims', bio: { "es": "El movimiento característico de Nakamura es atacar desde la izquierda para disparar. En los últimos años, se ha alejado del entrenamiento con pesas centrado en la parte superior del cuerpo y, en cambio, ha priorizado el desarrollo de su estilo fluido y evasivo que le permite deslizarse más allá de sus oponentes. También es conocido por usar calcetines bajos, al estilo Jack Grealish, lo que, según él, ayuda a reducir su tendencia a sufrir calambres musculares. Ha jugado al fútbol de su club en la Ligue 1 desde 2023 y ha estado vinculado con clubes de Inglaterra. Antes de este torneo, habló con Fifa.com sobre sus recuerdos de la Copa Mundial y dijo: \"Los torneos de 2018 y 2022 dejaron una huella en mí. En ambas ocasiones nos rompieron el corazón en octavos de final, pero significaron un paso más hacia adelante para nosotros como país. Recuerdo que se me puso la piel de gallina con solo ver jugar al equipo, y reforzó mi ambición de aparecer allí algún día. Esperamos volver a llegar a las fases eliminatorias e ir aún más lejos. Me encantaría poder hacerlo. contribuir a ese objetivo, aunque sea un poco... He soñado con jugar en la Copa del Mundo desde que era un niño pequeño”.", "en": "Nakamura’s signature move is cutting in from the left to shoot. In recent years he has moved away from upper-body-focused weight training, instead prioritising developing his fluid, evasive style that allows him to glide past opponents. He’s also known for wearing his socks low, Jack Grealish-style, which he says helps reduce his tendency to suffer from muscle cramps. He has played his club football in Ligue 1 since 2023, and has been linked with clubs in England. Before this tournament he spoke to Fifa.com about his World Cup memories, saying: “The 2018 and 2022 tournaments left their mark on me. Both times we got our hearts broken in the Last 16, but they signified one more step forward for us as a country. I remember getting goosebumps just watching the team play, and it reinforced my ambition to appear there one day myself. We’ll be hoping to reach the knockout stages again and go even further. I would love to be able to contribute towards that goal, even just a little … I’ve dreamed about playing in the World Cup since I was a little boy.”" } },
  { number: 14, name: 'Junya Ito', position: 'FW', age: 32, club: 'KRC Genk', bio: { "es": "Relativamente poco espectacular durante toda la escuela secundaria, Ito pasó a estudiar en la Universidad de Kanagawa, cuyos futbolistas juegan en la División 2 de Kanto de Japón. Allí construyó constantemente su reputación, y rápidamente llamó la atención con su ritmo excepcional. Después de graduarse, se unió al Ventforet Kofu de J1 en 2015 y al Kashiwa Reysol el año siguiente. Se mudó a Europa en 2019, primero a Genk en Bélgica, luego a Francia con Reims en 2022 antes de regresar a Genk el año pasado con un contrato de tres años. Es un gran jugador de impacto, a menudo sale desde el banquillo y tiene la capacidad de cambiar por completo el flujo de un partido. A pesar de su presencia explosiva y enérgica en el campo, él mismo admite que es bastante tímido en privado, una persona que se describe a sí misma como introvertida y que es más feliz en casa que saliendo en sus días libres.", "en": "Relatively unspectacular throughout high school, Ito went on to study at Kanagawa University, whose footballers play in Japan’s Kanto Division 2. He steadily built his reputation there, quickly gaining attention with his exceptional pace. After graduating he joined J1 side Ventforet Kofu in 2015 and Kashiwa Reysol the following year. He moved to Europe in 2019, first to Genk in Belgium, then to France with Reims in 2022 before returning to Genk last year on a three-year deal. He is great as an impact player, often coming off the bench, with the ability to completely change the flow of a match. Despite his explosive and energetic presence on the pitch, he is, by his own admission, quite shy in private, a self-described introvert who is happier at home than going out on his days off." } },
  { number: 18, name: 'Ayase Ueda', position: 'FW', age: 27, club: 'Feyenoord', bio: { "es": "Inspirado por su padre, que llevaba el número 18 en homenaje a su héroe, el ex internacional alemán Jürgen Klinsmann, Ueda eligió el mismo número para la selección nacional. Es un delantero talentoso, conocido por su inteligente lectura del juego, lleno de prolijas carreras diagonales y posicionamiento inteligente. \"Sólo el 10 por ciento final de una jugada de ataque -el gol en sí- depende de mí\", dijo. \"El otro 90 por ciento proviene de la preparación, por lo que mi papel es sacar a relucir las fortalezas de mis compañeros de equipo y convertirlo en un movimiento exitoso\". En el Mundial de hace cuatro años sólo participó en un partido, pero este verano, con más experiencia y un creciente sentido de responsabilidad, está decidido a dejar su huella en el escenario mundial. Se unió al Feyenoord en 2023 por £ 7 millones procedente del Cercle Brugge de Bélgica.", "en": "Inspired by his dad who wore the No18 in homage to his hero, the former Germany international Jürgen Klinsmann, Ueda chose the same number for the national team. He is a talented forward, known for smart reading of the game, full of neat diagonal runs and intelligent positioning. “Only the final 10 percent of an attacking move – the goal itself – is down to me,” he said. “The other 90 percent comes from the build-up, so my role is to bring out the strengths of my teammates and turn it into a successful move.” At the World Cup four years ago he featured in just one match, but this summer, with more experience and a growing sense of responsibility, he is determined to make his mark on the world stage. He joined Feyenoord in 2023 for £7m from Belgium’s Cercle Brugge." } },
  { number: 19, name: 'Koki Ogawa', position: 'FW', age: 28, club: 'NEC Nijmegen', bio: { "es": "Ogawa, un delantero fuerte y valiente capaz de cabecear, sostener el balón y rematar con cualquier pie, se inspira en su ídolo, Robert Lewandowski. En 2017 sufrió una grave lesión en la rodilla y quedó fuera del equipo de los Juegos Olímpicos de Tokio, afrontando un largo camino hacia la recuperación. Las oportunidades han ido y venido desde entonces, pero eso le ha enseñado mucho: “Afronto cada día como si fuera mi última oportunidad, dedicándolo todo al fútbol”, dice. \"Juego todos los partidos con la sensación de que estoy desesperado por conseguir goles\". Está empezando a dejar su huella en la Eredivisie, tras fichar por el NEC Nijmegen en 2023. A nivel internacional, sabe que hay competencia por las plazas, pero se respalda a sí mismo. \"Creo que probablemente soy el mejor goleador natural\", dijo a FIFA.com el año pasado. \"El trabajo de un delantero es marcar y, más que nada, me apoyo para encontrar la red y ayudar al equipo a ganar partidos... Quiero ser el tipo que aparece con un gol cuando el equipo más lo necesita\".", "en": "A strong, gritty all-round forward capable of heading, holding up the ball and finishing with either foot, Ogawa models himself on his idol, Robert Lewandowski. In 2017, he suffered a serious knee injury and was left out of the Tokyo Olympics squad, facing a long road to recovery. Opportunities have come and gone since, but it taught him plenty: “I approach every day as if it’s my last chance, throwing everything into football,” he says. “I play every match with the feeling that I’m desperate for goals.” He is starting to make his mark in the Eredivisie, having joined NEC Nijmegen in 2023. At international level, he knows there is competition for places, but backs himself. “I think I’m probably the best natural goalscorer,” he told Fifa.com last year. “A forward’s job is to score, and, more than anything, I back myself to find the net and help the team win matches … I want to be the guy who pops up with a goal when the team needs it the most.”" } },
  { number: 26, name: 'Kento Shiogai', position: 'FW', age: 21, club: 'Wolfsburg', bio: { "es": "Permaneció en gran parte desconocido hasta el verano de su último año de secundaria y pasó a estudiar en la universidad. Allí lució el número 10 y rápidamente destacó. Mientras aún estaba inscrito, consiguió un fichaje por el Yokohama F. Marinos, debutando en la J.League y marcando su primer gol apenas tres meses después. Luego se mudó al NEC Nijmegen antes de unirse al Wolfsburg en enero de este año, alcanzando una de las cinco mejores ligas de Europa en tan solo un año y medio. Su mayor arma es su extraordinaria aceleración, habiendo registrado una velocidad de sprint de 36,2 km/h. Incluso estudió la forma de carrera de Usain Bolt para refinar su explosividad, combinando ese ritmo con tiros potentes y regates dinámicos. En marzo de este año, consiguió su primera convocatoria para la selección nacional de Japón y asistió al gol de la victoria en su debut. Ahora forma parte del plantel mundialista.", "en": "Remained largely unknown until the summer of his final year of high school and went on to study at university. There, he wore the No 10 and quickly stood out. While still enrolled, he secured a move to Yokohama F. Marinos, making his J.League debut and scoring his first goal just three months later. He then moved to NEC Nijmegen before joining Wolfsburg in January this year, reaching one of Europe’s top five leagues in the span of just a year and a half. His greatest weapon is his extraordinary acceleration, having recorded a sprint speed of 36.2 km/h. He even studied Usain Bolt’s running form to refine his explosiveness, combining that pace with powerful shooting and dynamic dribbling. In March this year, he earned his first call-up to the Japan national team and assisted the winning goal on his debut. Now he is part of the World Cup squad." }, special: "Lightning quick" },
];

export const lineup = {
  formation: '3-4-3',
  startingXI: [1, 22, 21, 4, 17, 6, 7, 15, 13, 10, 8]
};
